    val len = s.length
    val target = "CODEFORCES"
    var flag = false

    for (i in 0..len) {
        val prefix = s.substring(0, i)
        val suffixStart = len - (10 - i)
        val suffix = if (suffixStart >= 0 && suffixStart <= len) s.substring(suffixStart) else ""
