import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val s = scanner.next()
    val len = s.length
    val target = "CODEFORCES"
    var flag = false

    for (i in 0..len) {
        val prefix = s.substring(0, i)
        val suffixStart = len - (10 - i)
        if (suffixStart < i || suffixStart > len) continue
        val suffix = s.substring(suffixStart, len)
        val candidate = prefix + suffix
        if (candidate == target) {
            flag = true
            break
        }
    }

    println(if (flag) "YES" else "NO")
}

